"""MIDAS Gen NX 适配器（模式 A，商业软件）—— 官方 Python SDK 版。

基于官方 `midas_gen` Python 库（`pip install midas-gen`）驱动，
不再手搓 HTTP 端点。凭证全部走环境变量，绝不写死进代码：

    MIDAS_API_URL      例：https://moa-engineers.midasit.cn:443/gen
    MIDAS_MAPI_KEY     官方 MAPI 鉴权（JWT）
    MIDAS_SECT_ID      要改写的截面 ID（默认 1）

未安装 midas_gen / 缺 Key 时，自动退化为占位（灰色·待接入），
保证 MACA 不依赖商业授权也能跑其它引擎。
"""

import os
import urllib.request
import urllib.error

from core.models import DesignParams, SolverResult
from core.solver import SolverBase, register

_E = float("nan")

# 官方 doc /db/SECT 的 PUT 请求体骨架（按 midas-rnd.github.io 文档推导）
_MOCK_SECT_BODY = {
    "Assign": {"1": {"b": None, "h": None, "material": None}},
}


@register
class MidasSdkAdapter(SolverBase):
    name = "MIDAS(NX)"
    mode = "commercial"
    note = "商业软件（midas Gen NX 官方 Python SDK）"

    def __init__(self):
        self.base_url = os.environ.get("MIDAS_API_URL", "").rstrip("/")
        self.mapi_key = ***REDACTED***"MIDAS_MAPI_KEY", "")
        self._sect_id = int(os.environ.get("MIDAS_SECT_ID", "1"))
        self._sdk = None
        self._sdk_err = ""

        self.available = bool(self.base_url and self.mapi_key)
        if self.available:
            try:
                from midas_gen import * as _g  # 官方 SDK 顶层函数
                self._sdk = _g
                # 把凭证喂给 SDK（内部再走 HTTP 打官方 MAPI）
                _g.MAPI_KEY(self.mapi_key)
                _g.MAPI_BASEURL(self.base_url)
            except Exception as e:
                self.available = False
                self._sdk_err = f"midas_gen SDK 不可用: {type(e).__name__}: {e}"
                self.note = "商业软件（midas Gen NX），SDK 未装/连接失败 → 占位"
        else:
            self.note = "商业软件（midas Gen NX），未接入（缺 Key/URL）→ 占位"

    # ---------- 对外契约 ----------
    def solve(self, p: DesignParams) -> SolverResult:
        if not self.available:
            why = self._sdk_err or "MIDAS_API_URL / MIDAS_MAPI_KEY 未配置"
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log=f"MIDAS 未接入: {why}",
            )
        try:
            return self._solve_with_sdk(p)
        except Exception as e:
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log=f"MIDAS SDK 调用失败: {type(e).__name__}: {e}",
            )

    # ---------- 官方 SDK 路径 ----------
    def _solve_with_sdk(self, p: DesignParams) -> SolverResult:
        g = self._sdk
        # 1. 改截面（用户截面 SB=实心矩形；b/h 单位与项目一致）
        #    这里假定模型已建好（节点+单元+材料），只把截面 ID 重写为新值
        g.Section.DBUSER(
            f"SEC{p.section_b}x{p.section_h}",
            "SB",
            [float(p.section_h) / 1000.0, float(p.section_b) / 1000.0],  # 米
            id=self._sect_id,
        )
        g.Section.create()

        # 2. 取结果（结果表）：最大位移 + 截面应力
        disp_df = g.Result.TABLE.Displacement(loadcase=["All"])
        stress_df = g.Result.TABLE.BeamStress(loadcase=["All"])

        disp_max = _max_abs(disp_df)
        stress_max = _max_abs(stress_df)

        # 3. 利用率与挠度判定
        stress_ratio = None
        if stress_max is not None and p.fy:
            stress_ratio = min(stress_max / p.fy, 2.0)
        ok = (
            stress_ratio is None or stress_ratio <= 1.0
        ) and (disp_max is None or disp_max <= p.max_serviceability_span_mm / 1000.0)

        return SolverResult(
            stress_ratio=round(stress_ratio, 4) if stress_ratio is not None else _E,
            deflection_mm=round(disp_max * 1000.0, 3) if disp_max is not None else _E,
            ok=bool(ok),
            engine=self.name,
            log=f"MIDAS SDK: σmax={_fmt(stress_max)}, δmax={_fmt(disp_max)}m, 利用率={_fmt(stress_ratio)}",
        )

    # ---------- 占位（SDK 不可用 / 模型为空时的兜底） ----------
    def _solve_mock(self, p: DesignParams) -> SolverResult:
        if not self.available:
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log="MIDAS SDK 不可用或当前项目截面模型为空，此引擎为占位，不参与计算",
            )
        # SDK 可用但模型空：如实报告
        sect = self._raw_req("GET", "/db/SECT")
        if not _has_content(sect):
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log="MIDAS API 已连通（鉴权通过），但当前项目截面模型为空 /db/SECT 无数据。"
                    "请先在 MIDAS 里建好梁模型（节点+截面+荷载）再跑本引擎。",
            )
        return SolverResult(
            stress_ratio=_E,
            deflection_mm=_E,
            ok=False,
            engine=self.name,
            log="MIDAS 模型存在但未配置完整结果提取，暂返回占位",
        )

    def _raw_req(self, method: str, path: str, body: dict | None = None):
        import json

        url = f"{self.base_url}{path}"
        data = json.dumps(body).encode() if body is not None else None
        req = urllib.request.Request(url, data=data, method=method)
        req.add_header("Content-Type", "application/json")
        req.add_header("MAPI-Key", self.mapi_key)
        with urllib.request.urlopen(req, timeout=30) as resp:
            raw = resp.read().decode() or "{}"
            try:
                return json.loads(raw)
            except json.JSONDecodeError:
                return {"raw": raw}


# ---------- helpers ----------
def _max_abs(df):
    """从 Polars DataFrame 取所有列的最大绝对值（位移/应力表都是数值列）。"""
    if df is None:
        return None
    try:
        cols = df.columns
        for c in cols:
            s = df[c]
            if s.dtype in ("Float64", "Float32", "Int64", "Int32"):
                s2 = s.abs().max()
                if s2 is not None:
                    return float(s2)
        return None
    except Exception:
        return None


def _fmt(v):
    if v is None:
        return "NA"
    try:
        return f"{float(v):.4f}"
    except Exception:
        return str(v)


def _has_content(r):
    if not isinstance(r, dict):
        return False
    for k in ("data", "sections", "sect", "result"):
        if r.get(k) not in (None, [], {}, ""):
            return True
    return False

"""MIDAS Gen NX —— 官方 Open API（REST）直连层。

按官方文档（midas-rnd.github.io/midasapi-python）的调用契约实现，
底层就是「带 MAPI-Key 的 HTTP 直连官方 MAPI 服务器」，无任何第三方中转：

    MAPI_KEY('eyJ...')               -> 每个请求头 Authorization 携带
    MAPI_BASEURL('https://moa-engineers.midasit.cn:443/gen')
    MidasAPI(method, command, body)  -> HTTP(method, base_url+command, json=body)

凭证只走环境变量（绝不写死进代码）：
    MIDAS_API_URL    https://moa-engineers.midasit.cn:443/gen
    MIDAS_MAPI_KEY   <你的 MAPI-Key>

不装任何第三方依赖（requests 在 venv 里已有）。
"""

import json
import os
import urllib.request
import urllib.error

_E = float("nan")

# ---- 凭证（环境变量注入） ----
API_URL = os.environ.get("MIDAS_API_URL", "").rstrip("/")
MAPI_KEY = ***REDACTED***"MIDAS_MAPI_KEY", "")


def is_available() -> bool:
    return bool(API_URL and MAPI_KEY)


def _auth_headers() -> dict:
    # 官方 MAPI 用 MAPI-Key 头鉴权（二进制里写死），兼容标准 Authorization
    return {
        "Content-Type": "application/json",
        "MAPI-Key": MAPI_KEY,
        "Authorization": f"Bearer {MAPI_KEY}",
    }


def MidasAPI(method: str, command: str, body: dict | None = None, timeout: int = 30):
    """官方调用契约的 REST 实现：MidasAPI("PUT", "/db/NODE", {...})。"""
    url = f"{API_URL}{command}"
    data = json.dumps(body).encode() if body is not None else None
    req = urllib.request.Request(url, data=data, method=method.upper(), headers=_auth_headers())
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode() or "{}"
            try:
                return json.loads(raw)
            except json.JSONDecodeError:
                return {"raw": raw, "http": resp.status}
    except urllib.error.HTTPError as e:
        raw = e.read().decode(errors="replace") or ""
        try:
            return {"http": e.code, "error": json.loads(raw)}
        except Exception:
            return {"http": e.code, "error": {"raw": raw[:500]}}
    except Exception as e:
        return {"error": {"message": f"{type(e).__name__}: {e}"}}


# ---- 高层封装（对应官方 SDK 的方法签名） ----
def Node(x, y, z, nid=None) -> dict:
    """官方 Node(x,y,z,id=...)：PUT /db/NODE。单位由项目 UNIT 决定（默认 mm）。"""
    body = {"Assign": {"1": {"X": float(x), "Y": float(y), "Z": float(z)}}}
    if nid is not None:
        body["Assign"][str(nid)] = body["Assign"].pop("1")
    return MidasAPI("PUT", "/db/NODE", body)


def Beam(n1, n2) -> dict:
    """官方 Element.Beam(n1, n2)：POST /db/ELEM。"""
    return MidasAPI("POST", "/db/ELEM", {"Type": "Beam", "Node1": int(n1), "Node2": int(n2)})


def DBUserSection(name, shape, params, sid=1) -> dict:
    """官方 Section.DBUSER('Rect_1x0.5','SB',[1.0,0.5],id)：PUT /db/SECT。"""
    return MidasAPI(
        "PUT", "/db/SECT",
        {"id": sid, "name": name, "shape": shape, "params": params},
    )


def Analyze() -> dict:
    """官方分析触发（MIDAS 里 Analysis -> 触发 /db 分析控制 + 求解）。"""
    # 先用 OPE/APISTART 会话，再触发分析，最后 OPE/APIEND
    MidasAPI("POST", "/OPE/APISTART", {})
    r = MidasAPI("POST", "/db/ANALYSIS", {"type": "Linear"})
    return r


def Results(kind="both") -> dict:
    """官方 Result.TABLE：位移/应力。这里走 /db/RESULT（字段名以服务器实际返回为准，
    做宽松提取；拿不到就不编造数值）。"""
    return MidasAPI("POST", "/db/RESULT", {"type": kind})


def _has_content(r: dict) -> bool:
    if not isinstance(r, dict):
        return False
    for k in ("data", "result", "sections", "sect", "message"):
        if r.get(k) not in (None, [], {}, ""):
            return True
    return False


def describe() -> str:
    if is_available():
        return f"✅ 已配置 MAPI 直连 {API_URL}（无第三方中转）"
    return "⚪ 未配置 MIDAS_API_URL / MIDAS_MAPI_KEY → 此引擎为占位"

"""MIDAS Gen NX MCP server（stdio，JSON-RPC 2.0）。

把「MACA 求解层」暴露成 MCP 工具，供 AI 客户端（AGH / Claude 等）直连调用。
底层全部走官方 MAPI REST 直连（adapters/midas_rest_client.py），无任何第三方中转。

暴露 3 个工具：
  list_engines   列出可用求解引擎（含 MIDAS 接入状态）
  solve_once     单次求解：DesignParams -> SolverResult（指定引擎，含 MIDAS(NX)）
  run_maca_agent 完整闭环：计算书 -> AI 决策 -> 迭代 -> 收敛

凭证走环境变量：
  MIDAS_API_URL / MIDAS_MAPI_KEY   （MIDAS）
  AGNES_API_KEY                    （可选，启用 LLM 决策；否则规则 fallback）

直接 stdio 运行：
  python mcp_server.py
（父进程按 MCP 协议发 {"jsonrpc":"2.0","method":"tools/list"} 等）
"""

import json
import os
import sys

# 让 core/ adapters/ ai/ 可导入
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import adapters  # noqa: F401  注册所有引擎（Formula / PyNite / MIDAS(NX)）
from core.solver import get, all_names, available_names
from core.models import DesignParams
from ai.decider import AIDecider
from core.agent import Agent
from adapters import midas_rest_client as midas


TOOLS = [
    {
        "name": "list_engines",
        "description": "列出 MACA 可用的求解引擎及接入状态（MIDAS 是否已配 MAPI）。",
        "inputSchema": {"type": "object", "properties": {}},
    },
    {
        "name": "solve_once",
        "description": "用指定引擎对一组设计参数做单次求解，返回应力比/挠度/ok。",
        "inputSchema": {
            "type": "object",
            "properties": {
                "engine": {"type": "string", "description": "FormulaEngine / PyNite / MIDAS(NX)"},
                "span_m": {"type": "number"},
                "wll_knm": {"type": "number", "description": "均布荷载 kN/m"},
                "fc_mpa": {"type": "number", "description": "混凝土抗压强度 MPa"},
                "fy_mpa": {"type": "number", "description": "钢筋抗拉强度 MPa"},
                "section_b": {"type": "number", "description": "截面宽 mm"},
                "section_h": {"type": "number", "description": "截面高 mm"},
                "as_area": {"type": "number", "description": "配筋面积 mm^2"},
            },
            "required": ["engine"],
        },
    },
    {
        "name": "run_maca_agent",
        "description": "跑完整 MACA 闭环：读计算书 -> AI 出建议 -> 迭代截面 -> 收敛。",
        "inputSchema": {
            "type": "object",
            "properties": {
                "book_text": {"type": "string", "description": "计算书原文"},
                "engine": {"type": "string", "description": "默认 FormulaEngine"},
                "max_iters": {"type": "integer"},
            },
            "required": ["book_text"],
        },
    },
]


def _handle_tool(name: str, args: dict):
    if name == "list_engines":
        return {
            "engines": all_names(),
            "available_now": available_names(),
            "midas_status": midas.describe(),
        }

    if name == "solve_once":
        p = DesignParams(
            span=float(args.get("span_m", 6.0)),
            wll=float(args.get("wll_knm", 20.0)),
            fc=float(args.get("fc_mpa", 30.0)),
            fy=float(args.get("fy_mpa", 300.0)),
            section_b=float(args.get("section_b", 200.0)),
            section_h=float(args.get("section_h", 300.0)),
            as_area=float(args.get("as_area", 1256.0)),
        )
        r = get(args.get("engine", "FormulaEngine")).solve(p)
        return {
            "engine": r.engine,
            "stress_ratio": r.stress_ratio,
            "deflection_mm": r.deflection_mm,
            "ok": r.ok,
            "log": r.log,
        }

    if name == "run_maca_agent":
        engine = args.get("engine", "FormulaEngine")
        max_iters = int(args.get("max_iters", 6))
        report = Agent(AIDecider(), engine=engine, max_iters=max_iters).run(args.get("book_text", ""))
        return {
            "converged": report.converged,
            "reason": report.reason,
            "final_section": report.final_result,
            "final_stress_ratio": report.final_stress_ratio,
            "final_deflection_mm": report.final_deflection_mm,
            "steps": [
                {
                    "step": s.step,
                    "section_label": s.section_label,
                    "stress_ratio": s.stress_ratio,
                    "deflection_mm": s.deflection_mm,
                    "ok": s.ok,
                    "engine": s.engine,
                    "suggestion": s.suggestion,
                }
                for s in report.steps
            ],
        }

    return {"error": f"unknown tool {name}"}


def _dispatch(request: dict) -> dict | None:
    method = request.get("method")
    rid = request.get("id")

    if method == "initialize":
        return {
            "jsonrpc": "2.0",
            "id": rid,
            "result": {
                "protocolVersion": "2024-11-05",
                "serverInfo": {"name": "maca-midas-mcp", "version": "1.0"},
                "capabilities": {"tools": {}},
            },
        }
    if method == "tools/list":
        return {"jsonrpc": "2.0", "id": rid, "result": {"tools": TOOLS}}
    if method == "tools/call":
        params = request.get("params", {})
        name = params.get("name")
        args = params.get("arguments", {}) or {}
        result = _handle_tool(name, args)
        return {"jsonrpc": "2.0", "id": rid, "result": {"content": [{"type": "text", "text": json.dumps(result, ensure_ascii=False, default=str)}]}}
    if method in ("notifications/initialized", "notifications/initialized"):
        return None
    # 未知方法：仅带 id 的才回错误
    if rid is not None:
        return {"jsonrpc": "2.0", "id": rid, "error": {"code": -32601, "message": f"method not found: {method}"}}
    return None


def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except json.JSONDecodeError:
            continue
        resp = _dispatch(req)
        if resp is not None:
            print(json.dumps(resp, ensure_ascii=False), flush=True)


if __name__ == "__main__":
    main()

"""MIDAS Gen NX —— 官方 Open API（MAPI RESTful）直连适配器。

官方唯一一套 API 就是 MAPI RESTful（Python SDK 文档：
midas-rnd.github.io/midasapi-python，JSON 接口手册：MIDAS API Online Manual）。

本适配器**不装第三方 SDK、不经过任何中转**：直接以你给的凭证
（MAPI_KEY + 中国区 BaseURL https://moa-engineers.midasit.cn:443/gen）
向官方 MAPI 端点发 HTTP/JSON，等价于官方 Python SDK 的底层行为：

    MAPI_KEY('<jwt>')           鉴权
    MAPI_BASEURL('https://...cn')
    MidasAPI(method, command, body)   <- 就是我们在这里做的事

端点（与官方 SDK 同一套 /db /OPE 体系）：
    /OPE/APISTART | /OPE/APIEND   会话开/关
    /db/NODE | /db/ELEM           建模
    /db/SECT                     截面（b/h）
    /db/ANALYSIS                 触发分析
    /db/RESULT                   取位移/应力

凭证走环境变量（绝不写死进代码）：
    MIDAS_API_URL      https://moa-engineers.midasit.cn:443/gen
    MIDAS_MAPI_KEY     <你的 MAPI JWT>
    MIDAS_SECT_ID      要改写的截面 ID（默认 1）

未配置 / 模型为空时自动退化为占位（灰色·待接入），保证 MACA 不依赖商业授权。
"""

import json
import os
import urllib.request
import urllib.error

from core.models import DesignParams, SolverResult
from core.solver import SolverBase, register

_E = float("nan")


@register
class MidasSdkAdapter(SolverBase):
    name = "MIDAS(NX)"
    mode = "commercial"
    note = "商业软件（midas Gen NX 官方 MAPI RESTful 直连）"

    def __init__(self):
        self.base_url = os.environ.get("MIDAS_API_URL", "").rstrip("/")
        self.mapi_key = ***REDACTED***"MIDAS_MAPI_KEY", "")
        self._sect_id = int(os.environ.get("MIDAS_SECT_ID", "1"))
        self.available = bool(self.base_url and self.mapi_key)
        if not self.available:
            self.note = "商业软件（midas Gen NX），未接入（缺 MAPI_KEY/URL）→ 占位"

    # ---------- 对外契约 ----------
    def solve(self, p: DesignParams) -> SolverResult:
        if not self.available:
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log="MIDAS 未接入：未设 MIDAS_API_URL / MIDAS_MAPI_KEY（官方 MAPI RESTful）",
            )
        try:
            return self._solve_midas(p)
        except Exception as e:
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log=f"MIDAS MAPI 调用失败: {type(e).__name__}: {e}",
            )

    # ---------- 官方 MAPI RESTful 调用（等价 SDK 的 MidasAPI()） ----------
    def _solve_midas(self, p: DesignParams) -> SolverResult:
        # 0. 探测：截面模型是否为空
        sect = self._req("GET", "/db/SECT")
        if not _has_content(sect):
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log="MIDAS MAPI 已连通（鉴权通过），但当前项目截面模型为空 /db/SECT 无数据。"
                    "请先在 MIDAS 里建好梁模型（节点+截面+荷载）再跑本引擎。",
            )

        # 1. 开会话
        self._req("POST", "/OPE/APISTART", {})
        # 2. 改截面（用户截面，形状码由项目决定；b/h 单位与项目一致）
        self._req("PUT", "/db/SECT", {
            "id": self._sect_id,
            "b": p.section_b,
            "h": p.section_h,
            "material": p.material,
        })
        # 3. 触发分析
        self._req("POST", "/db/ANALYSIS", {"type": "linear"})
        # 4. 取结果（位移 + 应力）
        res = self._req("POST", "/db/RESULT", {"type": "both"})
        data = res.get("data", res) if isinstance(res, dict) else {}

        stress = _first_present(data, ["stress_max", "max_stress", "sigma_max", "BeamStress"])
        defl = _first_present(data, ["deflection_max", "disp_max", "delta", "Displacement", "mid_deflection"])

        if stress is None and defl is None:
            return SolverResult(
                stress_ratio=_E,
                deflection_mm=_E,
                ok=False,
                engine=self.name,
                log="MIDAS MAPI 已连通但结果字段未对齐，原始返回: "
                    f"{json.dumps(data, ensure_ascii=False)[:300]}",
            )

        stress_ratio = _to_ratio(stress, p) if stress is not None else None
        ok = (
            (stress_ratio is None or stress_ratio <= 1.0)
            and (defl is None or float(defl) <= p.max_serviceability_span_mm)
        )
        return SolverResult(
            stress_ratio=round(stress_ratio, 4) if stress_ratio is not None else _E,
            utilization_detail={"raw": data},
            deflection_mm=round(float(defl), 3) if defl is not None else _E,
            ok=bool(ok),
            engine=self.name,
            log=f"MIDAS MAPI: σ={stress}, δ={defl}mm, 利用率={stress_ratio}",
        )

    # ---------- 底层 REST（等价官方 SDK 的 MidasAPI(method, command, body)） ----------
    def _req(self, method: str, path: str, body: dict | None = None) -> dict:
        url = f"{self.base_url}{path}"
        data = json.dumps(body).encode() if body is not None else None
        req = urllib.request.Request(url, data=data, method=method.upper())
        req.add_header("Content-Type", "application/json")
        # 官方 MAPI 鉴权头（二进制写死）+ 兼容标准 Authorization
        req.add_header("MAPI-Key", self.mapi_key)
        req.add_header("Authorization", f"Bearer {self.mapi_key}")
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                raw = resp.read().decode(errors="replace") or "{}"
                try:
                    return json.loads(raw)
                except json.JSONDecodeError:
                    return {"raw": raw}
        except urllib.error.HTTPError as e:
            raw = e.read().decode(errors="replace") or ""
            try:
                return {"http": e.code, "error": json.loads(raw)}
            except Exception:
                return {"http": e.code, "error": {"raw": raw[:300]}}


# ---------- helpers ----------
def _first_present(d: dict, keys: list):
    for k in keys:
        if k in d and d[k] is not None:
            return d[k]
    return None


def _has_content(r: dict) -> bool:
    if not isinstance(r, dict):
        return False
    for k in ("data", "sections", "sect", "result"):
        if r.get(k) not in (None, [], {}, ""):
            return True
    return False


def _to_ratio(stress_val, p: DesignParams):
    try:
        v = float(stress_val)
    except (TypeError, ValueError):
        return None
    if 0.0 <= v <= 2.0:
        return v
    return v / p.fy

