        "vCOMB": [{"ANAL": "ST", "LCNAME": "DL", "FACTOR": 1.2},
                   {"ANAL": "ST", "LCNAME": "LL", "FACTOR": 1.5}]}}
}


def _section_body(h_mm: float, b_mm: float) -> dict:
    """官方手册 §3：vSIZE=[H, B]，单位 m。"""
    return {"Assign": {"1": {
        "SECTTYPE": "DBUSER", "SECT_NAME": "Rectangular",
        "SECT_BEFORE": {"USE_SHEAR_DEFORM": True, "SHAPE": "SB", "DATATYPE": 2,
