    def solve(self, p: DesignParams) -> SolverResult:
        if not self.available:
            return SolverResult(
                stress_ratio=_E, deflection_mm=_E, ok=False, engine=self.name,
                log="MIDAS 未接入：未设 MIDAS_API_URL / MIDAS_MAPI_KEY（官方 MAPI RESTful）")
        try:
            return self._solve_midas(p)
        except Exception as e:
            return SolverResult(
                stress_ratio=_E, deflection_mm=_E, ok=False, engine=self.name,
                log=f"MIDAS MAPI 调用失败: {type(e).__name__}: {e}")

    # ---------- 官方 MAPI 完整闭环（建模 → 分析 → 取结果） ----------
    def _solve_midas(self, p: DesignParams) -> SolverResult:
        self._req("POST", "/OPE/APISTART", {})

        # 1. 建模：节点 / 截面 / 材料 / 单元 / 约束 / 荷载 / 组合
        self._req("PUT", "/db/NODE", {"Assign": {
            "1": {"X": 0, "Y": 0, "Z": 0},
