"""AutoCAD DXF → MACA DesignParams 轻量解析器。

设计目标：
    不依赖 ezdxf/重型 CAD 解析库，直接读 ASCII DXF 的常见关键字段；
    输出结构化 JSON + 候选 DesignParams，供 MACA Agent 做“关键性理解”。

典型输入：
    勒勒车2-2.dxf / 勒勒车3维图.dxf
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Iterable


@dataclass
class DxfExtraction:
    source: str
    ext_min: dict
    ext_max: dict
    layers: list
    line_count: int
    text_count: int
    circle_count: int
    keywords: dict
    candidate_params: dict
    warnings: list


def _read_groups(path: Path) -> Iterable[tuple[str, str]]:
    text = path.read_text(encoding="gbk", errors="ignore")
    lines = [line.rstrip("\n") for line in text.splitlines()]
    i = 0
    while i + 1 < len(lines):
        code = lines[i].strip()
        value = lines[i + 1]
        if code:
            yield code, value
        i += 2


def _iter_entities(groups: Iterable[tuple[str, str]]):
    in_entities = False
    current: dict[str, list[str]] = {}
    last_code = ""
    for code, value in groups:
        if code == "0":
            if in_entities and current:
                yield current
            in_entities = value.strip() == "SECTION" and False
            # DXF: SECTION start gives name in next code 2; handle below
            current = {"_entities": []}
            last_code = code
            continue
        if code == "2" and value.strip() == "ENTITIES":
            in_entities = True
            current = {}
            last_code = code
            continue
        if code == "0" and in_entities and value.strip() in {"LINE", "LWPOLYLINE", "POLYLINE", "TEXT", "MTEXT", "CIRCLE", "ARC", "SPLINE"}:
            if current:
                yield current
            current = {"TYPE": value.strip(), "FIELDS": {}}
            last_code = code
            continue
        if in_entities and current:
            if last_code == "0":
                current["TYPE"] = value.strip()
                current["FIELDS"] = {}
            else:
                current["FIELDS"].setdefault(code, []).append(value.strip())
            last_code = code
    if current:
        yield current


def extract_dxf(path: str | Path) -> DxfExtraction:
    p = Path(path)
    groups = list(_read_groups(p))
    entities = list(_iter_entities(groups))

    ext_min = {"X": 0.0, "Y": 0.0, "Z": 0.0}
    ext_max = {"X": 0.0, "Y": 0.0, "Z": 0.0}
    for code, value in groups:
        if code == "9" and value == "$EXTMIN":
            # next codes 10/20/30
            idx = groups.index((code, value))
            for k in range(1, 6):
                c, v = groups[idx + k]
                if c == "10":
                    ext_min["X"] = float(v)
                elif c == "20":
                    ext_min["Y"] = float(v)
                elif c == "30":
                    ext_min["Z"] = float(v)
        if code == "9" and value == "$EXTMAX":
            idx = groups.index((code, value))
            for k in range(1, 6):
                c, v = groups[idx + k]
                if c == "10":
                    ext_max["X"] = float(v)
                elif c == "20":
                    ext_max["Y"] = float(v)
                elif c == "30":
                    ext_max["Z"] = float(v)

    layer_names: list[str] = []
    for e in entities:
        pass

    # 读 LAYER section
    in_layer = False
    current_layer: dict = {}
    for code, value in groups:
        if code == "2" and value == "LAYER":
            in_layer = True
            continue
        if in_layer and code == "0" and value == "LAYER":
            if current_layer:
                layer_names.append(current_layer.get("name", ""))
            current_layer = {}
            continue
        if in_layer and code == "0" and value not in {"LAYER"}:
            in_layer = False
        if in_layer and current_layer == {} and code == "2":
            current_layer["name"] = value

    lines = [e for e in entities if e.get("TYPE") == "LINE"]
    texts = [e for e in entities if e.get("TYPE") in {"TEXT", "MTEXT"}]
    circles = [e for e in entities if e.get("TYPE") == "CIRCLE"]

    all_text = " ".join(
        " ".join(e["FIELDS"].get("1", [])) for e in texts
    )
    keywords = {
        "span": re.findall(r"(?:跨度|SPAN|span)\s*[:：]?\s*([0-9]+(?:\.[0-9]+)?)", all_text, flags=re.I),
        "load": re.findall(r"(?:kN/m|KN/m|荷载|LOAD)\s*[:：]?\s*([0-9]+(?:\.[0-9]+)?)", all_text, flags=re.I),
        "section": re.findall(r"(?:截面|SECTION)\s*[:：]?\s*([0-9]+(?:\.[0-9]+)?)[x×]([0-9]+(?:\.[0-9]+)?)", all_text, flags=re.I),
        "material": re.findall(r"(?:C30|C35|C40|HRB300|HRB400)", all_text, flags=re.I),
    }

    candidate: dict = {
        "auto_span_mm": round((ext_max["X"] - ext_min["X"]) * 1000, 1),
        "auto_height_mm": round((ext_max["Y"] - ext_min["Y"]) * 1000, 1),
        "text_span_candidates": [float(x) for x in keywords["span"]],
        "text_load_candidates": [float(x) for x in keywords["load"]],
        "text_section_candidates": [[float(a), float(b)] for a, b in keywords["section"]],
        "text_material_candidates": keywords["material"],
        "note": "DXF 几何自动提取跨度/高度为包围盒尺寸；文字关键词作为候选补充，需 AI 决策层确认。"
    }

    warnings = []
    if not lines:
        warnings.append("未提取到 LINE 实体，建议检查 DXF 是否为 R12 ASCII 且含线框。")
    if not keywords["span"]:
        warnings.append("未在 TEXT/MTEXT 中发现明确跨度文字，将用包围盒自动推断。")

    return DxfExtraction(
        source=str(p),
        ext_min=ext_min,
        ext_max=ext_max,
        layers=layer_names,
        line_count=len(lines),
        text_count=len(texts),
        circle_count=len(circles),
        keywords=keywords,
        candidate_params=candidate,
        warnings=warnings,
    )


def to_json(path: str | Path, out: str | Path | None = None) -> dict:
    ex = extract_dxf(path)
    d = asdict(ex)
    out_path = Path(out) if out else Path(path).with_suffix(".dxf.json")
    out_path.write_text(json.dumps(d, ensure_ascii=False, indent=2), encoding="utf-8")
    return d


if __name__ == "__main__":
    import sys
    if len(sys.argv) < 2:
        print("usage: python dxf_parser.py <file.dxf>")
