args.content:
"""AutoCAD DXF -> MACA 结构参数候选。

只做轻量解析，不碰 DWG 私有格式：
  - 支持 ASCII DXF；
  - 从 HEADER $EXTMIN/$EXTMAX 提取模型范围；
  - 从 LAYER/TEXT/MTEXT/LINE 提取结构线索；
  - 输出候选 DesignParams，供 Agent 决策层确认或覆盖。

现场目标：把“人工读 AutoCAD + 手建 MIDAS”的 3 小时，压成
DXF 导入 -> 自动参数 -> MIDAS MAPI 建模型/分析/迭代 的分钟级流程。
"""

from __future__ import annotations

import json
import re
from dataclasses import dataclass, asdict, field
from pathlib import Path
from typing import Any

DEFAULT_UNIT_HINT = "mm"


@dataclass
class DxfModel:
    source: str = ""
    layers: list[str] = field(default_factory=list)
    texts: list[str] = field(default_factory=list)
    line_count: int = 0
    circle_count: int = 0
    text_count: int = 0
    ext_min: dict[str, float] = field(default_factory=dict)
    ext_max: dict[str, float] = field(default_factory=dict)
    span_candidates_mm: list[float] = field(default_factory=list)
    section_candidates: list[tuple[float, float]] = field(default_factory=list)
    load_candidates: list[float] = field(default_factory=list)
    material_candidates: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)

    def auto_span_mm(self) -> float:
        if self.span_candidates_mm:
            # 取最接近常见梁跨范围的候选（0.5~30m），避免 CAD 图框尺寸干扰
            sane = [x for x in self.span_candidates_mm if 500 <= x <= 30000]
            if sane:
                return float(min(sane, key=lambda v: abs(v - 6000)))
        if self.ext_min and self.ext_max:
            w = abs(float(self.ext_max.get("X", 0)) - float(self.ext_min.get("X", 0)))
            h = abs(float(self.ext_max.get("Y", 0)) - float(self.ext_min.get("Y", 0)))
            # CAD 图常见 1:1 或 1:100/1:50，这里先按 1:1 mm 兜底，让 AI 决策层可覆盖
            return max(w, h)
        return 6000.0

    def best_span_mm(self) -> float:
        return self.auto_span_mm()

    def best_section(self) -> tuple[float, float]:
        if self.section_candidates:
            return self.section_candidates[0]
        return (250.0, 500.0)

    def to_design_params(self):
        from core.models import DesignParams

        b, h = self.best_section()
        p = DesignParams()
        p.span = float(self.best_span_mm())
        p.section_b = float(b)
        p.section_h = float(h)
        if self.load_candidates:
            p.wll = float(min(x for x in self.load_candidates if x > 0))
        if self.material_candidates:
            m = self.material_candidates[0].upper()
            p.material = m
            if "C30" in m:
                p.fc, p.fy = 14.3, 300.0
            elif "C35" in m:
                p.fc, p.fy = 15.7, 300.0
            elif "C40" in m:
                p.fc, p.fy = 19.1, 300.0
        p.notes = "DXF auto-parse candidate; review before MIDAS"
        return p


def _groups(path: Path) -> list[tuple[str, str]]:
    text = path.read_text(encoding="gb18030", errors="ignore")
    if text.startswith("\u0000") or "SECTION" not in text[:5000]:
        # 某些 CAD 导出带二进制头或 UTF-16 残量，退化为 GBK 可读部分
        text = path.read_text(encoding="gbk", errors="ignore")
    lines = [x.rstrip() for x in text.splitlines()]
    out: list[tuple[str, str]] = []
    i = 0
    while i + 1 < len(lines):
        code = lines[i].strip()
        val = lines[i + 1]
        if code:
            out.append((code, val))
        i += 2
    return out


def _entity_blocks(groups: list[tuple[str, str]]) -> list[dict[str, Any]]:
    entities = []
    in_entities = False
    current: dict[str, Any] | None = None
    i = 0
    while i < len(groups):
        code, val = groups[i]
        code = code.strip()
        val = val.strip()
        if code == "2" and val == "ENTITIES":
            in_entities = True
            continue
        if in_entities and code == "0":
            if current:
                entities.append(current)
            current = {"type": val, "layer": "", "texts": [], "coords": []}
            i += 1
            continue
        if in_entities and current is not None:
            if code == "8":
                current["layer"] = val
            if code in {"1", "10", "20", "30", "40"}:
                current["texts"].append(val)
            if code in {"10", "20", "30"}:
                try:
                    current["coords"].append(float(val))
                except ValueError:
                    pass
        i += 1
    if current:
        entities.append(current)
    return entities


def extract_dxf(path: str | Path) -> DxfModel:
    p = Path(path)
    model = DxfModel(source=str(p))

    groups = _groups(p)
    entities = _entity_blocks(groups)

    # HEADER EXTMIN/EXTMAX: code 9 -> $EXTMIN, then 10/20/30
    i = 0
    while i < len(groups):
        code, val = groups[i]
        if code == "9" and val in {"$EXTMIN", "$EXTMAX"}:
            key = "ext_min" if val == "$EXTMIN" else "ext_max"
            j = i + 1
            box = {}
            while j < len(groups) and groups[j][0] != "9":
                c, v = groups[j]
                if c == "10":
                    box["X"] = float(v)
                elif c == "20":
                    box["Y"] = float(v)
                elif c == "30":
                    box["Z"] = float(v)
                j += 1
            setattr(model, key, box)
            i = j
            continue
        i += 1

    layer_names = []
    in_layers = False
    for code, val in groups:
        if code == "2" and val == "LAYER":
            in_layers = True
            continue
        if in_layers and code == "0" and val == "LAYER":
            in_layers = True
            continue
        if in_layers and code == "2":
            layer_names.append(val)

    model.layers = layer_names[:100]

    text_blob_parts = []
    for e in entities:
        if e["type"].upper() in {"TEXT", "MTEXT", "ATTRIB", "ATTDEF"}:
            model.text_count += 1
            for t in e.get("texts", []):
                text_blob_parts.append(t)
        if e["type"].upper() == "LINE":
            model.line_count += 1
        if e["type"].upper() in {"CIRCLE", "ARC"}:
            model.circle_count += 1

    text_blob = " ".join(text_blob_parts)
    model.texts = [t for t in text_blob_parts if t.strip()][:200]

    # CAD 文字里的跨度：优先识别 500-30000 的数字；避免图框 420/297
    span_digits = re.findall(r"(\d{2,5}(?:\.\d+)?)", text_blob)
    span_set: list[float] = []
    for x in span_digits:
        v = float(x)
        if 500 <= v <= 30000 and v not in span_set:
            span_set.append(v)
    model.span_candidates_mm = span_set[:20]

    # 截面：AxB / BxA / 250x500 / 250×500
    section_pat = re.findall(r"(\d{2,4})\s*[xX×]\s*(\d{2,4})", text_blob)
    seen_sec: set[tuple[float, float]] = set()
    for a, b in section_pat:
        x, y = float(a), float(b)
        if 50 <= x <= 2000 and 50 <= y <= 4000 and (x, y) not in seen_sec:
            model.section_candidates.append((x, y))
            seen_sec.add((x, y))

    # 荷载：kN/m 数字，其次 “荷载 20”
    load_pat = re.findall(r"(\d+(?:\.\d+)?)\s*(?:kN/m|KN/M)", text_blob, flags=re.I)
    for x in load_pat:
        model.load_candidates.append(float(x))
    if not model.load_candidates:
        for m in re.finditer(r"(?:荷载|恒载|活载|均布)\s*[:：]?\s*(\d+(?:\.\d+)?)", text_blob, flags=re.I):
            model.load_candidates.append(float(m.group(1)))

    mat_pat = re.findall(r"\bC(?:30|35|40|50)\b|HRB(?:300|400)\b", text_blob, flags=re.I)
    model.material_candidates = list(dict.fromkeys(m.upper() for m in mat_pat))[:10]

    if not model.span_candidates_mm and not model.line_count:
        model.warnings.append("DXF 未提取到明显跨度文字或线框，跨度将使用包围盒/默认 6m 候选，需 AI 决策确认。")
    if not model.section_candidates:
        model.warnings.append("DXF 未提取到 AxB 截面文字，将使用默认 250x500 候选，需 AI 决策确认。")
    return model


def extract_dxf_json(path: str | Path, out: str | Path | None = None) -> dict:
    model = extract_dxf(path)
    data = asdict(model)
    data["auto_span_mm"] = model.auto_span_mm()
    data["best_span_mm"] = model.best_span_mm()
    data["best_section"] = model.best_section()
    target = Path(out) if out else Path(path).with_suffix(".dxf.json")
    target.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding="utf-8")
    return data


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        print("usage: python dxf_parser.py <file.dxf>")
        raise SystemExit(2)
    print(json.dumps(extract_dxf_json(sys.argv[1]), ensure_ascii=False, indent=2))

