"""DXF 实体级勘查：把真实 CAD 里到底有什么，原样数出来（只读，不改码）。

目的：不再靠"默认简支梁参数"猜结构；先把实体账目摸清。
输出：logs/cad_survey.json
"""

from __future__ import annotations

import json
import re
import sys
from collections import Counter
from pathlib import Path


def read_pairs(path: Path) -> list[tuple[str, str]]:
    """DXF ASCII: 成对的 (组码, 值)。"""
    raw = path.read_bytes()
    for enc in ("gb18030", "utf-8", "latin-1"):
        try:
            text = raw.decode(enc)
            break
        except UnicodeDecodeError:
            continue
    else:
        text = raw.decode("utf-8", errors="replace")
    text = text.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")
    pairs: list[tuple[str, str]] = []
    i = 0
    while i + 1 < len(lines):
        code = lines[i].strip()
        val = lines[i + 1].strip()
        if code:
            pairs.append((code, val))
        i += 2
    return pairs


def survey(path: Path) -> dict:
    pairs = read_pairs(path)
    out: dict = {"file": str(path), "size_bytes": path.stat().st_size, "pair_count": len(pairs)}

    # 实体计数：组码 0 后面跟实体类型
    entities = Counter()
    for code, val in pairs:
        if code == "0" and val:
            entities[val] += 1
    out["entity_counts"] = dict(entities.most_common(60))

    # 图层
    layers: Counter = Counter()
    for i, (code, val) in enumerate(pairs):
        if code == "8":
            layers[val] += 1
    out["layer_counts"] = dict(layers.most_common(40))

    # 文本实体（TEXT / MTEXT 的 1 组码）
    texts: list[str] = []
    in_text = False
    for code, val in pairs:
        if code == "0":
            in_text = val in ("TEXT", "MTEXT", "ATTRIB")
        elif in_text and code == "1" and val:
            texts.append(val)
    out["text_count"] = len(texts)
    out["texts_sample"] = texts[:80]

    # 尺寸标注（DIMENSION 的 1 组码 + 测量值 42）
    dims: list[float] = []
    for code, val in pairs:
        if code == "42":
            try:
                dims.append(float(val))
            except ValueError:
                pass
    out["dimension_measures"] = dims[:120]
    out["dimension_count"] = len(dims)

    # 坐标范围（组码 10/20 = 起点，11/21 = 端点）
    xs: list[float] = []
    ys: list[float] = []
    for code, val in pairs:
        if code in ("10", "11"):
            try:
                xs.append(float(val))
            except ValueError:
                pass
        elif code in ("20", "21"):
            try:
                ys.append(float(val))
            except ValueError:
                pass
    if xs and ys:
        out["bbox"] = {"xmin": min(xs), "xmax": max(xs), "ymin": min(ys), "ymax": max(ys),
                       "width": max(xs) - min(xs), "height": max(ys) - min(ys)}

    # 关键词扫描（截面 / 荷载 / 材料 / 跨度）
    blob = "\n".join(texts)
    out["keywords"] = {
        "section": re.findall(r"\d{2,4}\s*[xX×]\s*\d{2,4}", blob),
        "load": re.findall(r"\d+(?:\.\d+)?\s*kN(?:/m)?", blob, re.I),
        "material": re.findall(r"C\d{2}|HRB\d{3}|Q\d{3}", blob, re.I),
        "span": re.findall(r"[Ll]\s*=\s*\d+(?:\.\d+)?", blob),
    }
    return out


def main() -> int:
    root = Path(__file__).resolve().parent.parent
    targets = sorted(root.glob("*.dxf"))
    if len(sys.argv) > 1:
        targets = [Path(sys.argv[1])]
    results = []
    for t in targets:
        try:
            r = survey(t)
            results.append(r)
            print(f"=== {t.name} ===")
            print(f"  pairs={r['pair_count']}  texts={r['text_count']}  dims={r['dimension_count']}")
            print(f"  layers={list(r['layer_counts'])[:8]}")
            print(f"  top_entities={list(r['entity_counts'].items())[:10]}")
            if "bbox" in r:
                b = r["bbox"]
                print(f"  bbox={b['width']:.1f} x {b['height']:.1f}")
        except Exception as e:
            print(f"=== {t.name} === FAILED: {type(e).__name__}: {e}")

    out_dir = Path(__file__).resolve().parent / "logs"
    out_dir.mkdir(parents=True, exist_ok=True)
    p = out_dir / "cad_survey.json"
    p.write_text(json.dumps(results, ensure_ascii=False, indent=2), encoding="utf-8")
    print(f"\nwritten: {p}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

