            break
if disp:
    mx = max(disp, key=lambda t: abs(t[1])+abs(t[2])+abs(t[3]))
    print(f'.XOUT 位移 {len(disp)} 节点, 最大合成@node{mx[0]} DZ={mx[3]:.3f}mm')
